package br.com.romenig.plataforma.perfil.foto;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import javax.imageio.ImageIO;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.MediaType;
import org.springframework.transaction.annotation.Transactional;
import br.com.romenig.plataforma.usuario.CodificadorDeSenha;
import tools.jackson.databind.ObjectMapper;
@SpringBootTest @AutoConfigureMockMvc @Transactional
class FotoPerfilTest {
 @Autowired MockMvc http;@Autowired JdbcTemplate jdbc;@Autowired CodificadorDeSenha senhas;@Autowired ObjectMapper json;
 String token(String email)throws Exception{jdbc.update("INSERT INTO usuario(nome,email,senha_hash,perfil_id) VALUES('Aluno',?,?,(SELECT id FROM perfil WHERE nome='ALUNO'))",email,senhas.codificar("senha1234"));return json.readTree(http.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("email",email,"senha","senha1234")))).andReturn().getResponse().getContentAsString()).path("token").asText();}
 byte[] foto(String formato,int largura,int altura)throws Exception{var b=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(largura,altura,BufferedImage.TYPE_INT_RGB),formato,b);return b.toByteArray();}
 org.springframework.test.web.servlet.ResultActions enviar(String t,byte[] bytes,String mime)throws Exception{return http.perform(multipart("/api/perfil/foto").file(new MockMultipartFile("arquivo","foto",mime,bytes)).header("Authorization","Bearer "+t));}
 @Test void exigeAutenticacaoEPerfilSemFoto()throws Exception{http.perform(get("/api/perfil/foto")).andExpect(status().isUnauthorized());http.perform(delete("/api/perfil/foto")).andExpect(status().isUnauthorized());http.perform(multipart("/api/perfil/foto").file(new MockMultipartFile("arquivo",foto("png",2,2)))).andExpect(status().isUnauthorized());String t=token("foto.a@email.com");http.perform(get("/api/perfil/foto").header("Authorization","Bearer "+t)).andExpect(status().isNoContent());http.perform(get("/api/perfil").header("Authorization","Bearer "+t)).andExpect(jsonPath("$.temFoto").value(false));}
 @Test void salvaNormalizaJPEGSubstituiPNGEPersiste()throws Exception{String t=token("foto.b@email.com");byte[] normalizada=enviar(t,foto("jpeg",1000,500),"image/jpeg").andExpect(status().isOk()).andExpect(content().contentType("image/png")).andReturn().getResponse().getContentAsByteArray();var imagem=ImageIO.read(new ByteArrayInputStream(normalizada));assertThat(imagem.getWidth()).isEqualTo(512);assertThat(imagem.getHeight()).isEqualTo(256);http.perform(get("/api/perfil/foto").header("Authorization","Bearer "+t)).andExpect(content().bytes(normalizada)).andExpect(header().string("Cache-Control","no-store"));enviar(t,foto("png",3,4),"image/png").andExpect(status().isOk());byte[] salva=http.perform(get("/api/perfil/foto").header("Authorization","Bearer "+t)).andReturn().getResponse().getContentAsByteArray();assertThat(ImageIO.read(new ByteArrayInputStream(salva)).getWidth()).isEqualTo(3);assertThat(jdbc.queryForObject("SELECT count(*) FROM foto_perfil",Integer.class)).isEqualTo(1);}
 @Test void outroAlunoNaoLeOuSubstituiFoto()throws Exception{String a=token("foto.c@email.com"),b=token("foto.d@email.com");byte[] original=enviar(a,foto("png",5,6),"image/png").andReturn().getResponse().getContentAsByteArray();http.perform(get("/api/perfil/foto").header("Authorization","Bearer "+b)).andExpect(status().isNoContent());enviar(b,foto("png",2,2),"image/png").andExpect(status().isOk());http.perform(delete("/api/perfil/foto").header("Authorization","Bearer "+b)).andExpect(status().isNoContent());http.perform(get("/api/perfil/foto").header("Authorization","Bearer "+a)).andExpect(content().bytes(original));}
 @Test void arquivoFalsoTamanhoOuDimensoesInvalidosPreservamFoto()throws Exception{String t=token("foto.e@email.com");byte[] salva=enviar(t,foto("png",2,2),"image/png").andReturn().getResponse().getContentAsByteArray();for(byte[] invalida:new byte[][]{"arquivo falso".getBytes(),new byte[0],new byte[NormalizadorFoto.LIMITE_BYTES+1],foto("png",4097,1),foto("gif",2,2)})enviar(t,invalida,"image/png").andExpect(status().isBadRequest()).andExpect(jsonPath("$.erros[0].campo").value("foto"));http.perform(get("/api/perfil/foto").header("Authorization","Bearer "+t)).andExpect(content().bytes(salva));}
 @Test void removerFotoEIdempotenteENaoMudaOutrosDados()throws Exception{String t=token("foto.f@email.com");enviar(t,foto("png",2,2),"image/png").andExpect(status().isOk());http.perform(get("/api/perfil").header("Authorization","Bearer "+t)).andExpect(jsonPath("$.temFoto").value(true));for(int i=0;i<2;i++)http.perform(delete("/api/perfil/foto").header("Authorization","Bearer "+t)).andExpect(status().isNoContent());http.perform(get("/api/perfil").header("Authorization","Bearer "+t)).andExpect(jsonPath("$.temFoto").value(false)).andExpect(jsonPath("$.nome").value("Aluno")).andExpect(jsonPath("$.email").value("foto.f@email.com"));assertThat(jdbc.queryForObject("SELECT count(*) FROM foto_perfil",Integer.class)).isZero();}
 @Test void editarNomePreservaFotoECorsPermiteRemocao()throws Exception{String t=token("foto.g@email.com");byte[] original=enviar(t,foto("png",2,2),"image/png").andReturn().getResponse().getContentAsByteArray();http.perform(put("/api/perfil").header("Authorization","Bearer "+t).contentType(MediaType.APPLICATION_JSON).content("{\"nome\":\"Nome alterado\",\"email\":\"foto.g@email.com\",\"metaEstudoSemanal\":10,\"objetivoMotivacao\":null}")).andExpect(status().isOk()).andExpect(jsonPath("$.temFoto").value(true));http.perform(get("/api/perfil/foto").header("Authorization","Bearer "+t)).andExpect(content().bytes(original));http.perform(options("/api/perfil/foto").header("Origin","http://localhost:5173").header("Access-Control-Request-Method","DELETE")).andExpect(status().isOk()).andExpect(header().string("Access-Control-Allow-Methods",org.hamcrest.Matchers.containsString("DELETE")));}
}
